import * as THREE from '../classroom-chase/three.module.min.js';
import {createGame,step,jump,reset,respawn} from './engine.js';
import {setupTouchControls,bindInstantAction} from '../shared/touch-controls.js?v=1';
import {bindViewDrag} from '../classroom-chase/view-drag.js?v=1';
import {installMouseLook} from '../shared/mouse-look.js?v=1';
import {installFullscreen} from '../lizard-evolution/fullscreen.js';
const $=s=>document.querySelector(s), canvas=$('#game'), stage=$('.stage'), game=createGame();
const renderer=new THREE.WebGLRenderer({canvas,antialias:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=THREE.SRGBColorSpace;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x94c4ef);scene.fog=new THREE.Fog(0x94c4ef,55,160);
const camera=new THREE.PerspectiveCamera(72,1,.1,200);scene.add(new THREE.HemisphereLight(0xffffff,0x9b8870,2));const sun=new THREE.DirectionalLight(0xffffff,1.2);sun.position.set(-20,50,15);scene.add(sun);
function texture(base,tones){const c=document.createElement('canvas');c.width=c.height=16;const x=c.getContext('2d');x.fillStyle=base;x.fillRect(0,0,16,16);let seed=23;for(let i=0;i<115;i++){seed=(seed*1664525+1013904223)>>>0;const px=seed%16;seed=(seed*1664525+1013904223)>>>0;const py=seed%16;x.fillStyle=tones[seed%tones.length];x.fillRect(px,py,1+(seed%2),1)}const t=new THREE.CanvasTexture(c);t.magFilter=THREE.NearestFilter;t.minFilter=THREE.NearestFilter;t.colorSpace=THREE.SRGBColorSpace;return t}
const grass=new THREE.MeshLambertMaterial({map:texture('#5c9d3c',['#6faf45','#4f8b32','#82b852'])}),dirt=new THREE.MeshLambertMaterial({map:texture('#795335',['#956c46','#62452f','#a07950'])}),stone=new THREE.MeshLambertMaterial({map:texture('#898c8c',['#777979','#a4a5a2','#686b6c'])}),checkpoint=new THREE.MeshLambertMaterial({map:texture('#55b5c2',['#93e4eb','#398d9d','#c1f6ef'])}),gold=new THREE.MeshLambertMaterial({map:texture('#e6ba3a',['#ffe97f','#c99019','#fff0a5'])});
const blocks=game.platforms.map(p=>{const top=p.finish?gold:p.checkpoint?checkpoint:grass;const material=[dirt,dirt,top,stone,dirt,dirt];const mesh=new THREE.Mesh(new THREE.BoxGeometry(p.w,.9,p.w),material);mesh.position.set(p.x,p.y-.45,p.z);scene.add(mesh);return mesh});
// Square clouds and distant islands give the sky a pixel-block feel.
const cloudMaterial=new THREE.MeshLambertMaterial({color:0xffffff});for(let i=0;i<19;i++){const cloud=new THREE.Mesh(new THREE.BoxGeometry(4+(i%3)*2,.4,2),cloudMaterial);cloud.position.set((i%5-2)*20,11+(i%3)*3,-i*7);scene.add(cloud)}
let yaw=0,pitch=-.18,playing=false,joyX=0,joyY=0,sneakToggle=false,last=0,oldCheckpoint=0,toastTimer;const keys=new Set(),held=new Map();
const turnView=(dx,dy)=>{yaw-=dx*.005;pitch=Math.max(-1.35,Math.min(1.35,pitch-dy*.005))};
const stopJoystick=setupTouchControls((x,y)=>{joyX=x;joyY=y},()=>clearInput());const stopView=bindViewDrag(canvas,()=>playing&&document.pointerLockElement!==canvas,turnView);const releaseMouse=installMouseLook(canvas,()=>playing,turnView);document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement===canvas)stopView()});
function clearInput(){keys.clear();held.clear();joyX=joyY=0;stopJoystick();stopView()}
function sneaking(){return sneakToggle||keys.has('shift')}
function updateSneak(){const active=sneaking();$('#sneak').textContent=`SNEAK: ${sneakToggle?'ON':'OFF'}`;$('#sneak').setAttribute('aria-pressed',String(sneakToggle));$('#sneak-status').hidden=!active}
function showToast(text){$('#toast').textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',2200)}
function start(){if(game.won){reset(game);oldCheckpoint=0;yaw=0;pitch=-.18}clearInput();sneakToggle=false;updateSneak();playing=true;$('#overlay').hidden=true;last=0}
$('#start').addEventListener('click',start);$('#restart').addEventListener('click',()=>{reset(game);oldCheckpoint=0;yaw=0;pitch=-.18;start()});$('#return').addEventListener('click',()=>{if(!playing)return;game.deaths++;respawn(game);clearInput();showToast('Back to checkpoint')});
bindInstantAction($('#jump'),()=>{if(playing)jump(game)});$('#sneak').addEventListener('click',()=>{sneakToggle=!sneakToggle;updateSneak()});
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' ','shift','q','e','r','f'].includes(k))e.preventDefault();if(k===' '&&!e.repeat&&playing)jump(game);keys.add(k);updateSneak()});window.addEventListener('keyup',e=>{keys.delete(e.key.toLowerCase());updateSneak()});
for(const button of document.querySelectorAll('[data-control]')){button.addEventListener('pointerdown',e=>{e.preventDefault();held.set(e.pointerId,button.dataset.control);try{button.setPointerCapture(e.pointerId)}catch{}});for(const event of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(event,e=>held.delete(e.pointerId))}
for(const event of ['blur','pagehide'])window.addEventListener(event,clearInput);document.addEventListener('visibilitychange',()=>{if(document.hidden)clearInput()});
installFullscreen($('#game-root'),$('#fullscreen'));const active=(name,...keyboard)=>[...held.values()].includes(name)||keyboard.some(k=>keys.has(k));
function resize(){const w=stage.clientWidth,h=stage.clientHeight;if(canvas.width!==Math.round(w*renderer.getPixelRatio())||canvas.height!==Math.round(h*renderer.getPixelRatio())){renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}}
function frame(now){const dt=last?Math.min((now-last)/1000,.04):0;last=now;resize();if(playing){let forward=(active('forward','w','arrowup')?1:0)-(active('back','s','arrowdown')?1:0)-joyY,side=(active('right','d','arrowright')?1:0)-(active('left','a','arrowleft')?1:0)+joyX;yaw+=((active('turnLeft','q')?1:0)-(active('turnRight','e')?1:0))*dt*1.7;pitch=Math.max(-1.35,Math.min(1.35,pitch+((active('lookUp','r')?1:0)-(active('lookDown','f')?1:0))*dt));step(game,-Math.sin(yaw)*forward+Math.cos(yaw)*side,-Math.cos(yaw)*forward-Math.sin(yaw)*side,dt,sneaking());if(game.checkpoint!==oldCheckpoint){oldCheckpoint=game.checkpoint;showToast('Checkpoint reached!')}if(game.won){playing=false;releaseMouse();clearInput();$('#title').textContent='You made it! 🎉';$('#message').textContent=`Amazing! You conquered the course with ${game.deaths} falls.`;$('#start').textContent='Play again';$('#overlay').hidden=false}}
for(let i=0;i<blocks.length;i++)blocks[i].position.x=game.platforms[i].x;const p=game.player;camera.position.set(p.x,p.y+(sneaking()?1.32:1.62),p.z);camera.rotation.set(pitch,yaw,0,'YXZ');$('#checkpoint').textContent=`Checkpoint ${Math.floor(game.checkpoint/6)+1} / 4`;$('#falls').textContent=`Falls: ${game.deaths}`;renderer.render(scene,camera);requestAnimationFrame(frame)}requestAnimationFrame(frame);
